.app {
  display: grid;
  grid-template-columns: 300px 1fr;
  min-height: 100vh;
}

.app--sidebar-collapsed {
  grid-template-columns: auto 1fr;
}

.app__sidebar-wrapper {
  position: sticky;
  top: 0;
  height: 100vh;
  overflow: visible;
}

.app__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px;
  border-bottom: 1px solid var(--color-border-light);
  flex-shrink: 0;
}

.app__header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.app__main {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 24px;
  flex: 1;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
}

.app__empty {
  text-align: center;
  color: var(--color-text-disabled);
  font-size: 14px;
  margin-top: 32px;
  padding: 0 12px;
  line-height: 1.5;
}

.app__title {
  margin: 0;
  font-size: 22px;
  font-weight: 700;
  color: var(--color-text-primary);
}

.app__theme-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  padding: 0;
  background: none;
  border: none;
  border-radius: 8px;
  color: var(--color-text-muted);
  cursor: pointer;
}

.app__theme-toggle:hover {
  background: var(--color-bg-hover-strong);
  color: var(--color-text-primary);
}

.app__lang-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 34px;
  height: 34px;
  padding: 0 6px;
  background: none;
  border: none;
  border-radius: 8px;
  color: var(--color-text-muted);
  cursor: pointer;
  font-size: 13px;
  font-weight: 600;
}

.app__lang-toggle:hover {
  background: var(--color-bg-hover-strong);
  color: var(--color-text-primary);
}

.app__agent-toggle {
  height: 34px;
  padding: 0 14px;
  font-size: 13px;
  font-weight: 600;
  border: 1px solid var(--color-accent-primary);
  border-radius: 8px;
  background: var(--color-bg-primary);
  color: var(--color-accent-primary);
  cursor: pointer;
  white-space: nowrap;
}

.app__agent-toggle:hover {
  background: var(--color-bg-user-msg);
}

.app__agent-toggle--active {
  background: var(--color-accent-primary);
  color: #fff;
}

.app__agent-toggle--active:hover {
  background: var(--color-accent-primary-hover);
}

.app__agent-wrapper,
.app__editor-wrapper {
  display: flex;
  flex-direction: column;
  height: 100vh;
  min-width: 0;
}

.app__mode-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 24px;
  border-bottom: 1px solid var(--color-border-light);
  background: var(--color-bg-primary);
}

.app__mode-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--color-text-secondary);
}

.app-loading,
.app-error {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  font-size: 16px;
  color: var(--color-text-muted);
}

.app-error {
  color: var(--color-error-text);
}

